import{J as e,n as t,ot as n,q as r}from"./chunks/framework.W-fY_xnt.js";var i=JSON.parse(`{"title":"Implement the NetherNet protocol in @jsprismarine/nethernet","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Implement the NetherNet protocol in @jsprismarine/nethernet"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/adr/0007-own-nethernet-protocol"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/adr/0007-own-nethernet-protocol"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/adr/0007-own-nethernet-protocol.md"}},"headers":[],"relativePath":"adr/0007-own-nethernet-protocol.md","filePath":"adr/0007-own-nethernet-protocol.md","lastUpdated":1794440303000}`),a={name:`adr/0007-own-nethernet-protocol.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="implement-the-nethernet-protocol-in-jsprismarine-nethernet" tabindex="-1">Implement the NetherNet protocol in <code>@jsprismarine/nethernet</code> <a class="header-anchor" href="#implement-the-nethernet-protocol-in-jsprismarine-nethernet" aria-label="Permalink to “Implement the NetherNet protocol in @jsprismarine/nethernet”">​</a></h1><p>Status: accepted. Replaces the requirement in <a href="/pr-preview/pr-2987/plans/nethernet-transport.html">the NetherNet plan</a> to use the npm <code>nethernet</code> package for the WebRTC side.</p><p>The server and our client ran NetherNet through <code>nethernet</code> (PrismarineJS&#39;s node-nethernet), with <code>@jsprismarine/nethernet</code> beside it for HTTP signaling, the identity, the LAN advertisement and join by address. We now write the rest ourselves, in TypeScript, in <code>@jsprismarine/nethernet</code>: offer, answer and candidate handling for server and client, the connection&#39;s message segmentation, the LAN discovery packets with their encryption, and the signal format. The npm package and <code>protodef</code> leave the workspace.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><ul><li><strong>The WebRTC stack has to be ours to choose.</strong> <code>nethernet</code> picks its stack by name, <code>werift</code> or <code>wrtc</code>, and takes no other. <a href="/pr-preview/pr-2987/adr/0006-libdatachannel-for-nethernet-server.html">ADR 0006</a> moves NetherNet to libdatachannel, and getting a third stack in meant replacing a field on its <code>Server</code>.</li><li><strong>Its werift workarounds are for a werift we do not run.</strong> It pins werift 0.24.4 and patches around two of that release&#39;s bugs. We run 0.27 for its SCTP fixes, where both patches misfire, and <code>adaptPeerConnections</code> existed to undo them.</li><li><strong>It hands us untyped objects.</strong> The server read the peer connection through <code>unknown</code> and guards, to learn a player&#39;s address and to drain a kick.</li><li><strong>It cannot be compiled ahead of time.</strong> It builds its packet codec at run time with <code>protodef</code>&#39;s compiler, which generates code and runs it with <code>eval</code>. The scriptc build needs code that exists at build time.</li><li><strong>The client gets what the server gets.</strong> One implementation, taking a WebRTC driver as an option, serves both.</li></ul><h2 id="what-it-costs" tabindex="-1">What it costs <a class="header-anchor" href="#what-it-costs" aria-label="Permalink to “What it costs”">​</a></h2><ul><li>About 1,500 lines of JavaScript to replace, and the wire compatibility that came with them. The LAN discovery encryption and the segmentation are the parts a mistake would break silently.</li><li>We stop receiving <code>nethernet</code>&#39;s fixes and protocol updates, and have to follow Bedrock&#39;s changes ourselves.</li></ul><h2 id="how-we-keep-it-compatible" tabindex="-1">How we keep it compatible <a class="header-anchor" href="#how-we-keep-it-compatible" aria-label="Permalink to “How we keep it compatible”">​</a></h2><p>Our client already joins Bedrock Dedicated Server in its tests, and cinnabar, a Bedrock client, joins our server in the client end-to-end suite. Those two run our code against implementations we did not write, in both directions, and are the check. <code>nethernet</code> is removed in the slice that replaces it.</p><h2 id="alternatives-not-taken" tabindex="-1">Alternatives not taken <a class="header-anchor" href="#alternatives-not-taken" aria-label="Permalink to “Alternatives not taken”">​</a></h2><p><strong>Ask <code>nethernet</code> for a backend option.</strong> It solves the first reason and none of the others, and depends on a release we do not control.</p><p><strong>Keep swapping the backend object it holds.</strong> It works today and breaks when the package changes how it builds peer connections, without a type error.</p><p><strong>Fork <code>nethernet</code>.</strong> A fork keeps the JavaScript, the <code>protodef</code> codec and the werift patches, and adds a package to publish.</p></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};